'use strict';
// One selection model for the roster, formation board and match launch.
function lineupPool(){return (UI.ctx?.draft?G.cup?.teams?.P:G.clubs.P.roster||[]).map(id=>G.beasts[id]).filter(Boolean)}
function lineupCapacity(c=UI.ctx){if(!c)return 5;return c.kind==='league'?5:c.kind==='trial'?TRIALS[c.trial].fmt:G.cup?.fmt||c.fmt||5}
function selectableBeast(id){const pool=lineupPool(),b=pool.find(x=>x.id===id);return !!b&&(!b.inj||pool.filter(x=>!x.inj).length<lineupCapacity())}
function normalizeLineup(fill=false){if(!UI.ctx)return;UI.ctx.fmt=lineupCapacity();const pool=lineupPool(),valid=new Set(pool.map(b=>b.id));UI.sel=[...new Set(UI.sel)].filter(id=>valid.has(id)&&selectableBeast(id)).slice(0,UI.ctx.fmt);if(fill)for(const b of pool.slice().sort((a,b)=>lineScore(b)-lineScore(a)))if(UI.sel.length<UI.ctx.fmt&&!UI.sel.includes(b.id)&&selectableBeast(b.id))UI.sel.push(b.id);normalizeFormation();}
function normalizeFormation(){const used=new Set();for(const [i,id] of UI.sel.entries()){const b=G.beasts[id];if(!b)continue;let p=initialFormation(b,i);const legal=p&&Number.isInteger(p.col)&&Number.isInteger(p.row)&&p.col>=0&&p.col<3&&p.row>=0&&p.row<5;if(!legal||used.has(`${p.col}:${p.row}`)){const col={back:0,flank:1,front:2}[b.tactics.pos]??1;const slots=Array.from({length:15},(_,n)=>({col:n%3,row:Math.floor(n/3)})).sort((a,z)=>Math.abs(a.col-col)-Math.abs(z.col-col)||Math.abs(a.row-2)-Math.abs(z.row-2));p=slots.find(p=>!used.has(`${p.col}:${p.row}`))}b.formation={...p};used.add(`${p.col}:${p.row}`)}if(!UI.sel.includes(UI.formBeast))UI.formBeast=UI.sel[0]||null}
function persistLineup(){if(!UI.ctx?.draft)G.lineups[lineupCapacity()]=UI.sel.slice();save()}
const flowSetPrematch=setPrematch;setPrematch=function(c){c.fmt=lineupCapacity(c);flowSetPrematch(c);normalizeLineup(true);UI.replaceWith=null;persistLineup();render()};
const flowStartMatch=startMatch;startMatch=function(watch){normalizeLineup();if(UI.sel.length!==lineupCapacity()){toast(`Choose ${lineupCapacity()} heroes for this match.`);return}flowStartMatch(watch)};
function placeLineupBeast(id,col,row){if(UI.mode!=='prematch'||!selectableBeast(id)||!Number.isInteger(col)||!Number.isInteger(row)||col<0||col>2||row<0||row>4)return false;normalizeLineup();if(UI.sel.includes(id))return moveFormation(id,col,row);const occupant=UI.sel.find(x=>{const p=G.beasts[x].formation;return p.col===col&&p.row===row});if(UI.sel.length>=lineupCapacity()&&!occupant){toast(`All ${lineupCapacity()} places are filled. Drop onto a hero to swap.`);return false}if(occupant)UI.sel[UI.sel.indexOf(occupant)]=id;else UI.sel.push(id);G.beasts[id].formation={col,row};G.beasts[id].tactics.pos=['back','flank','front'][col];UI.formBeast=id;UI.replaceWith=null;normalizeFormation();return true}
function chooseLineupBeast(id){if(UI.mode!=='prematch'||!selectableBeast(id))return;if(UI.sel.includes(id)){if(UI.replaceWith){const p=G.beasts[id].formation;if(placeLineupBeast(UI.replaceWith,p.col,p.row)){persistLineup();render()}return}UI.formBeast=id;render();return}if(UI.sel.length<lineupCapacity()){UI.sel.push(id);UI.formBeast=id;normalizeFormation();persistLineup()}else UI.replaceWith=id;render()}
ACT.lineupChoose=d=>chooseLineupBeast(d.id);
for(const key of ['next','toPrematch']){const previous=ACT[key];ACT[key]=(...args)=>{previous(...args);if(UI.mode==='prematch'){normalizeLineup();persistLineup();render()}}}
ACT.lineupCancel=()=>{UI.replaceWith=null;render()};
ACT.sel=d=>chooseLineupBeast(d.id);
ACT.unsel=d=>{if(UI.mode!=='prematch')return;UI.sel=UI.sel.filter(id=>id!==d.id);UI.replaceWith=null;normalizeFormation();persistLineup();render()};
ACT.autopick=()=>{if(UI.mode!=='prematch')return;UI.sel=pickLineup('P',lineupCapacity()).map(b=>b.id);normalizeLineup(true);UI.replaceWith=null;persistLineup();render()};
ACT.formSelect=d=>chooseLineupBeast(d.id);
ACT.formPlace=d=>{const id=UI.replaceWith||(UI.sel.includes(UI.formBeast)?UI.formBeast:UI.sel[0]);if(id&&placeLineupBeast(id,+d.col,+d.row)){persistLineup();render()}};
const flowRestoreFormation=ACT.formLoad;ACT.formLoad=()=>{flowRestoreFormation();normalizeFormation();persistLineup();render()};
function formatExplanation(){return UI.ctx.kind==='league'?'League matches field five heroes.':UI.ctx.kind==='trial'?`This preseason bout fields ${lineupCapacity()} ${lineupCapacity()===1?'hero':'heroes'}. Your league team will field five.`:`This cup is ${lineupCapacity()}v${lineupCapacity()}. Your league lineup still has five places.`}
formationHtml=function(){const members=UI.sel.map(id=>G.beasts[id]),selected=G.beasts[UI.replaceWith||UI.formBeast];return `<section class="panel formation-panel direct-formation"><div class="formation-heading"><div><span class="lbl gold">YOUR OPENING FORMATION</span><h3>${UI.sel.length} / ${lineupCapacity()} heroes fielded</h3></div><span class="format-badge">${lineupCapacity()}v${lineupCapacity()}</span></div><p class="note">${UI.replaceWith?`Choose a hero to replace with ${esc(selected.name)}.`:'Drag heroes from the bench onto the board. Drop onto another hero to swap.'}</p>${UI.replaceWith?'<button class="btn sm" data-act="lineupCancel">Cancel swap</button>':''}<div class="formation-labels"><span>BACK</span><span>MIDDLE</span><span>FRONT →</span></div><div class="formation-board">${Array.from({length:15},(_,i)=>{const col=i%3,row=Math.floor(i/3),b=members.find(b=>b.formation?.col===col&&b.formation?.row===row);return `<button class="formation-cell ${b?.id===UI.formBeast?'selected':''} ${b&&UI.replaceWith?'swap-candidate':''}" data-act="formPlace" data-col="${col}" data-row="${row}" data-occupant="${b?.id||''}" aria-label="${b?esc(b.name)+'; ':''}${['back','middle','front'][col]} row ${row+1}">${b?`<span class="formation-unit" data-drag-unit="${b.id}">${beastArt(b.sp)}<span>${esc(b.name)}</span></span>`:'<i>+</i>'}</button>`}).join('')}</div><details class="formation-options"><summary>Opening timing & saved layouts</summary><label class="note">Hold formation <select data-chg="opening" aria-label="Opening duration">${[0,1,2,3,4,5].map(n=>`<option value="${n}" ${(G.opening??2)===n?'selected':''}>${n}s</option>`).join('')}</select></label><button class="btn sm" data-act="formSave">Save formation</button><button class="btn sm" data-act="formLoad" ${G.savedFormation?.[UI.ctx.fmt]?'':'disabled'}>Restore formation</button></details></section>`};
function lineupCard(b,fielded){return `<article class="lineup-card ${fielded?'fielded':''} ${UI.replaceWith===b.id?'pending-swap':''}" data-drag-unit="${b.id}"><button class="lineup-face" data-act="lineupChoose" data-id="${b.id}" ${!selectableBeast(b.id)?'disabled':''} aria-label="${UI.replaceWith&&fielded?'Replace ':fielded?'Select ':UI.sel.length>=lineupCapacity()?'Swap in ':'Field '}${esc(b.name)}">${beastArt(b.sp)}<span><strong>${esc(b.name)}</strong><small>${SPECIES[b.sp].role} · ${b.energy} energy${b.inj?' · injured':''}</small></span></button><div class="lineup-card-actions"><button class="linkbtn" data-act="profile" data-id="${b.id}" data-pt="tactics">Tactics</button>${fielded?`<button class="linkbtn" data-act="unsel" data-id="${b.id}" aria-label="Bench ${esc(b.name)}">Bench</button>`:`<button class="linkbtn" data-act="lineupChoose" data-id="${b.id}" ${!selectableBeast(b.id)?'disabled':''}>${b.inj&&!selectableBeast(b.id)?'Recovering':UI.sel.length>=lineupCapacity()?'Swap in':'Field hero'}</button>`}</div></article>`}
viewPrematch=function(){const c=UI.ctx,oc=G.clubs[c.opp],pool=lineupPool(),sel=UI.sel.map(id=>G.beasts[id]),opponents=c.draft?G.cup.teams[c.opp].map(id=>G.beasts[id]):pickLineup(c.opp,c.fmt);return `<div class="match-intro"><div><span class="lbl gold">${esc(campaignLabel(c))}</span><h2>${esc(G.name)} <span>vs</span> ${esc(oc.name)}</h2><p>${formatExplanation()}</p></div><div class="match-format"><b>${lineupCapacity()}v${lineupCapacity()}</b><span>${UI.sel.length} / ${lineupCapacity()} selected</span></div></div><div class="match-workbench">${formationHtml()}<section class="panel lineup-picker" data-guide="lineup"><div class="row between"><h3>Your team</h3><button class="linkbtn" data-act="autopick">Suggest lineup</button></div><p class="note">${UI.replaceWith?'Tap a fielded hero or its tile to complete the swap.':'Tap a benched hero to field it, or drag it onto a tile.'}</p><div class="lineup-list">${sel.map(b=>lineupCard(b,true)).join('')}</div><div class="lbl bench-heading">BENCH · ${pool.length-sel.length}</div><div class="lineup-list">${pool.filter(b=>!UI.sel.includes(b.id)).map(b=>lineupCard(b,false)).join('')}</div></section></div>${readinessHtml()}<details class="panel opponent-details" data-guide="scouting"><summary>Scout ${esc(oc.name)} · expected lineup & advice</summary><div class="opponent-strip">${opponents.map(b=>`<button data-act="profile" data-id="${b.id}">${beastArt(b.sp)}<strong>${esc(b.name)}</strong><small>${SPECIES[b.sp].role} · OVR ${ovr(b)}</small></button>`).join('')}</div><ul class="tips">${scoutTips(sel,opponents).map(t=>`<li>${esc(t)}</li>`).join('')}</ul></details>`};

// Results are the background; earned powers and active techniques are modal card choices.
function rewardKind(b){if(!b)return null;if(b.awaken?.length)return 'trait';if(techniquePoints(b)>0&&techniquePool(b).some(k=>(b.techniques?.[k]||0)<3&&(Object.keys(b.techniques||{}).length<2||b.techniques?.[k])))return 'technique';if(b.rolls>0&&Object.keys(PERKS).some(k=>(b.perks?.[k]||0)<PERKS[k].max&&!(k==='blades'&&SPECIES[b.sp].range>=60)))return 'power';return null}
function remainingRewards(){return (UI.lvq||[]).filter(id=>rewardKind(G.beasts[id]))}
function openRewardCards(){UI.lvq=remainingRewards();if(!UI.lvq.length)return false;UI.mode='levelup';UI.modal={k:'reward'};UI.result.rewardRevision=UI.result.rewardRevision||0;save();render();return true}
const rewardsFinish=finishMatch;finishMatch=function(S){const before=UI.result;rewardsFinish(S);if(UI.result===before)return;UI.lvq=UI.result.rows.filter(r=>r.team===0&&G.beasts[r.bid]?.clubId==='P'&&rewardKind(G.beasts[r.bid])).map(r=>r.bid);UI.lvTotal=UI.lvq.length;if(!openRewardCards())save()};
advanceLv=function(){UI.lvq=remainingRewards();if(UI.lvq.length){UI.mode='levelup';UI.modal={k:'reward'}}else{UI.mode='result';UI.modal=null}save();render()};
viewLevelUp=function(){return viewResult()};
function rewardActionAllowed(d){return UI.mode==='levelup'&&UI.modal?.k==='reward'&&UI.lvq?.[0]===d.id&&Number(d.rev)===(UI.result.rewardRevision||0)}
function rewardRevision(){UI.result.rewardRevision=(UI.result.rewardRevision||0)+1}
ACT.rewardPerk=d=>{if(!rewardActionAllowed(d)||!G.beasts[d.id].offer?.includes(d.k))return;rewardRevision();ACT.perk(d)};
ACT.rewardTechnique=d=>{if(!rewardActionAllowed(d)||!learnTechnique(G.beasts[d.id],d.k))return;rewardRevision();playCue('upgrade');advanceLv()};
ACT.rewardTrait=d=>{if(!rewardActionAllowed(d)||!G.beasts[d.id].awaken?.includes(d.k))return;rewardRevision();ACT.awaken(d)};
ACT.rewardReroll=d=>{if(!rewardActionAllowed(d)||G.gold<rerollCost(G.beasts[d.id]))return;rewardRevision();ACT.reroll(d)};
ACT.rewardLater=()=>{if(!UI.result)return;UI.mode='result';UI.modal=null;save();render()};
ACT.resnext=()=>{if(openRewardCards())return;UI.modal=null;resultNext();if(UI.mode==='hub'&&curEvent())openNext()};
const rewardClose=ACT.close;ACT.close=d=>{if(UI.modal?.k==='reward')ACT.rewardLater();else rewardClose(d)};
const rewardScrim=ACT.scrim;ACT.scrim=(d,el,e)=>{if(UI.modal?.k==='reward'){if(e.target===el)ACT.rewardLater()}else rewardScrim(d,el,e)};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&UI.modal?.k==='reward'){e.preventDefault();e.stopImmediatePropagation();ACT.rewardLater()}},true);
function modalReward(){const b=G.beasts[UI.lvq[0]],kind=rewardKind(b),rev=UI.result.rewardRevision||0,progress=Math.max(1,(UI.lvTotal||UI.lvq.length)-UI.lvq.length+1);let cards='';const action=(act,k,label)=>`<button class="btn pri" data-act="${act}" data-id="${b.id}" data-k="${k}" data-rev="${rev}">${label}</button>`;
 if(kind==='power'){if(!b.offer)rollOffer(b);cards=(b.offer||[]).map(k=>upgradeCard(b,k,action('rewardPerk',k,'Choose '+esc(perkName(b,k))))).join('')}
 if(kind==='technique')cards=techniquePool(b).filter(k=>(b.techniques?.[k]||0)<3&&(Object.keys(b.techniques||{}).length<2||b.techniques?.[k])).map(k=>{const t=TECHNIQUES[k],rank=(b.techniques?.[k]||0)+1;return `<article class="pcard technique-reward" style="--pc:#91c8d9"><span class="ptier">ACTIVE ABILITY · ${rank===1?'NEW':'RANK '+rank}</span><div class="perk-icon">${t.icon}</div><b>${t.n}${rank>1?' '+['','I','II','III'][rank]:''}</b><p>${t.d}</p><span class="reward-cooldown">${t.cd}s cooldown · casts automatically</span>${action('rewardTechnique',k,rank===1?'Learn ability':'Upgrade ability')}</article>`}).join('');
 if(kind==='trait')cards=b.awaken.map(k=>`<article class="pcard" style="--pc:#d4b878"><span class="ptier">AWAKENING</span><div class="perk-icon">✧</div><b>${esc(k)}</b><p>${esc(TRAITS[k])}</p>${action('rewardTrait',k,'Choose trait')}</article>`).join('');
 return `<div class="reward-heading">${tok(b,'big')}<div><span class="lbl gold">ROUND COMPLETE · HERO ${progress} / ${UI.lvTotal||UI.lvq.length}</span><h2>${esc(b.name)} grows stronger.</h2><p>${kind==='technique'?'Choose an active ability.':kind==='trait'?'Choose a new trait.':'Choose one power.'} It carries into your next match.</p></div></div><div class="pcards reward-cards">${cards}</div><div class="reward-footer"><span>${SPECIES[b.sp].n} · Level ${b.lvl} · ${kind==='technique'?techniquePoints(b)+' ability '+(techniquePoints(b)===1?'point':'points'):kind==='power'?b.rolls+' power '+(b.rolls===1?'choice':'choices'):'New awakening'}</span>${kind==='power'?`<button class="btn sm" data-act="rewardReroll" data-id="${b.id}" data-rev="${rev}" ${G.gold<rerollCost(b)?'disabled':''}>Reroll · ${rerollCost(b)} gold</button>`:''}<button class="btn sm" data-act="rewardLater">Review match</button></div>`;
}
const rewardsRenderModal=renderModal;renderModal=function(){if(UI.mode==='levelup'&&remainingRewards().length)UI.modal={k:'reward'};rewardsRenderModal();if(UI.modal?.k==='reward')document.querySelector('.sheet')?.classList.add('reward-sheet')};
const rewardsLoad=load;load=function(){const g=rewardsLoad();if(g?.resume?.result){const q=(g.resume.lvq||[]).filter(id=>{const b=g.beasts[id];return b&&(b.rolls>0||b.awaken?.length||techniquePoints(b)>0)});UI.lvq=q;UI.lvTotal=g.resume.lvTotal||q.length;if(q.length&&g.resume.rewardOpen){UI.mode='levelup';UI.modal={k:'reward'}}}return g};
const rewardsSave=save;save=function(){const ok=rewardsSave();if(G?.resume){G.resume.rewardOpen=UI.mode==='levelup';try{localStorage.setItem(SAVE_KEY,JSON.stringify(G))}catch{return false}}return ok};
const rewardResult=viewResult;viewResult=function(){let h=rewardResult();if(!remainingRewards().length)h=h.replace(/(<button class="btn pri" data-act="resnext">)[\s\S]*?(<\/button>)/,'$1Prepare next match →$2');return h};
